# Kaggle extracts ZIP uploads into the private input dataset.
choices=list(Path('/kaggle/input').rglob('INVENTORY.json'))
matching=[p for p in choices if json.loads(p.read_text())==INVENTORY]
assert len(matching)==1, 'exact uploaded source inventory not found'
INPUT=matching[0].parent
SOURCE=ROOT/'source';SOURCE.mkdir()
SEALED_ARCHIVE=base64.b64decode('')
for name,digest in INVENTORY.items():
    p=INPUT/name
    raw=SEALED_ARCHIVE if name=='research/frem_s10_kaggle_20261016/source_bundle.zip' else p.read_bytes()
    assert hashlib.sha256(raw).hexdigest()==digest, name
    q=SOURCE/name;q.parent.mkdir(parents=True,exist_ok=True);q.write_bytes(raw)
patched=base64.b64decode('')
assert hashlib.sha256(patched).hexdigest()=='3542e1885329484b01428bc6feb1b89ade00ac024882185e9fa234ff1638b0dd'
(SOURCE/'successors/frem_s10/src/frem_s10/experiment/replay.py').write_bytes(patched)
INVENTORY['successors/frem_s10/src/frem_s10/experiment/replay.py']='3542e1885329484b01428bc6feb1b89ade00ac024882185e9fa234ff1638b0dd'
(ROOT/'source-inventory.json').write_text(json.dumps(INVENTORY,sort_keys=True))
BOOT=SOURCE/'tools/kaggle/bootstrap.py'
spec=importlib.util.spec_from_file_location('suite_boot',BOOT);boot=importlib.util.module_from_spec(spec);spec.loader.exec_module(boot)
PYTHON=boot.prepare(ROOT/'runtime',(SOURCE/'tools/kaggle/requirements-cpu.txt').read_text())
ENV=boot.clean_environment(ROOT/'runtime')
ENV.update(OPENBLAS_NUM_THREADS='1',OMP_NUM_THREADS='1',MKL_NUM_THREADS='1',NUMEXPR_NUM_THREADS='1',VECLIB_MAXIMUM_THREADS='1',PYTEST_DISABLE_PLUGIN_AUTOLOAD='1',PYTHONPATH=str(SOURCE/'successors/frem_s10/src'))
uv=ROOT/'runtime/tools/bin/uv'
# Locate only the installed pinned uv binary from bootstrap.
assert uv.is_file(), str(uv)
with (ROOT/'test-dependencies.log').open('xb') as log:
    subprocess.run([str(uv),'pip','install','--python',str(PYTHON),'pytest==8.4.2'],env=ENV,stdout=log,stderr=subprocess.STDOUT,timeout=120,check=True)
with (ROOT/'package-install.log').open('xb') as log:
    subprocess.run([str(uv),'pip','install','--python',str(PYTHON),'--no-deps','-e',str(SOURCE/'successors/frem_s10')],env=ENV,stdout=log,stderr=subprocess.STDOUT,timeout=120,check=True)
GUARD=SOURCE/'tools/kaggle/namespace_guard.py'
spec=importlib.util.spec_from_file_location('namespace_observation',GUARD);guard=importlib.util.module_from_spec(spec);spec.loader.exec_module(guard)
def admission():
    rows=[]
    for i in range(3):
        if i:time.sleep(1)
        rows.append(guard.sample())
    result=guard.assess(rows)
    result.update(status='GENERATED_TESTS_ONLY_ADMITTED',contract='s10-kaggle-generated-tests-v1',cpu_seconds_per_process=600,command_wall_seconds=900)
    return result
assert not Path('/dev/nvidia0').exists()
commands=[('s10', [str(PYTHON),'-B','-m','pytest','-c','successors/frem_s10/pyproject.toml','successors/frem_s10/tests','-q','-W','error','-p','no:cacheprovider','--s10-receipt',str(ROOT/'pytest-observations.json'),'--junitxml',str(ROOT/'junit.xml')]), ('wrappers',[str(PYTHON),'-B','-m','unittest','discover','-s','tools/kaggle','-p','test_*.py','-v'])]
def limits():
    for kind,ceiling in [(resource.RLIMIT_AS,1024*2**20),(resource.RLIMIT_CPU,600)]:
        old=resource.getrlimit(kind);bound=min([ceiling]+[x for x in old if x!=resource.RLIM_INFINITY]);resource.setrlimit(kind,(bound,bound))
    resource.setrlimit(resource.RLIMIT_CORE,(0,0))
results=[]
for name,cmd in commands:
    pre=admission();(ROOT/(name+'-admission.json')).write_text(json.dumps(pre))
    start=time.monotonic(); print('START',name,flush=True)
    with (ROOT/(name+'.log')).open('xb') as stream:
        p=subprocess.Popen(cmd,cwd=SOURCE,env=ENV,stdout=stream,stderr=subprocess.STDOUT,start_new_session=True,preexec_fn=limits)
        error=None
        try:
            while p.poll() is None:
                if time.monotonic()-start>900: raise TimeoutError('900 second command ceiling')
                row=guard.sample()
                if row['available_bytes']<512*2**20 or any(row[k]!=pre['samples'][-1][k] for k in ('pswpout','events','membership','mount')):
                    raise RuntimeError('resource pressure changed')
                time.sleep(1)
        except BaseException as exc:
            error=repr(exc)
            try:os.killpg(p.pid,signal.SIGKILL)
            except ProcessLookupError:pass
            p.wait(timeout=5)
        post=guard.sample()
        result={'name':name,'exit_code':p.returncode,'error':error,'seconds':time.monotonic()-start,'postflight':post}
        results.append(result)
    print((ROOT/(name+'.log')).read_text()[-24000:],flush=True)
    print(json.dumps(result),flush=True)
(ROOT/'runtime-identity.json').write_text(subprocess.check_output([str(PYTHON),'-c',"import sys,platform,importlib.metadata,json;print(json.dumps({'python':sys.version,'platform':platform.platform(),'packages':{d.metadata['Name']:d.version for d in importlib.metadata.distributions()}}))"],env=ENV,text=True,timeout=10))
(ROOT/'results.json').write_text(json.dumps({'scope':'all maintained S10 tests and Kaggle wrappers','results':results,'scientific_status':'NOT_EVALUATED','production_qualified':False},indent=2))
artifact=Path('/kaggle/working/s10-full-tests-attempt3-results.zip')
with zipfile.ZipFile(artifact,'w',zipfile.ZIP_DEFLATED) as z:
    for p in ROOT.iterdir():
        if p.is_file():z.write(p,p.name)
print('RESULT_ARCHIVE',str(artifact),hashlib.sha256(artifact.read_bytes()).hexdigest(),flush=True)
assert all(r['exit_code']==0 and r['error'] is None for r in results), 'full suite has failures; retained logs require repair'
print('FULL_SUITE_COMPLETE',flush=True)
